CREATE TABLE IF NOT EXISTS `Counters` (`id` int NOT NULL AUTO_INCREMENT, `count` int NOT NULL DEFAULT 1, `createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP, `updatedAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, PRIMARY KEY (`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS users (id BIGINT NOT NULL AUTO_INCREMENT, user_openid VARCHAR(128) NOT NULL, nickname VARCHAR(100), avatar_url VARCHAR(500), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, PRIMARY KEY(id), UNIQUE KEY uk_users_openid(user_openid)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS recipe_categories (id BIGINT NOT NULL AUTO_INCREMENT, name VARCHAR(100) NOT NULL, sort_order INT DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(id), UNIQUE KEY uk_category_name(name)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS recipes (id BIGINT NOT NULL AUTO_INCREMENT, user_openid VARCHAR(128) NOT NULL, category_id BIGINT, title VARCHAR(200) NOT NULL, description TEXT, cover_url VARCHAR(500), difficulty VARCHAR(30), cooking_time INT, servings INT, is_public TINYINT DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, PRIMARY KEY(id), KEY idx_recipe_user(user_openid), KEY idx_recipe_category(category_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS recipe_ingredients (id BIGINT NOT NULL AUTO_INCREMENT, recipe_id BIGINT NOT NULL, name VARCHAR(100) NOT NULL, amount VARCHAR(100), sort_order INT DEFAULT 0, PRIMARY KEY(id), KEY idx_ingredient_recipe(recipe_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS recipe_steps (id BIGINT NOT NULL AUTO_INCREMENT, recipe_id BIGINT NOT NULL, step_no INT NOT NULL, content TEXT NOT NULL, image_url VARCHAR(500), PRIMARY KEY(id), KEY idx_step_recipe(recipe_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS recipe_images (id BIGINT NOT NULL AUTO_INCREMENT, recipe_id BIGINT NOT NULL, image_url VARCHAR(500) NOT NULL, sort_order INT DEFAULT 0, PRIMARY KEY(id), KEY idx_image_recipe(recipe_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS cooking_records (id BIGINT NOT NULL AUTO_INCREMENT, user_openid VARCHAR(128) NOT NULL, recipe_id BIGINT, recipe_title VARCHAR(200), cooked_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, note VARCHAR(500), PRIMARY KEY(id), KEY idx_record_user(user_openid), KEY idx_record_recipe(recipe_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS recipe_favorites (id BIGINT NOT NULL AUTO_INCREMENT, user_openid VARCHAR(128) NOT NULL, recipe_id BIGINT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(id), UNIQUE KEY uk_favorite(user_openid, recipe_id), KEY idx_favorite_recipe(recipe_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
INSERT IGNORE INTO recipe_categories(name, sort_order) VALUES ('家常菜', 1), ('快手菜', 2), ('汤羹', 3), ('烘焙', 4);
